import io, re
import dotenv.parser as p

cases = {
 "crlf+lf (acceptance)": "X=1\r\nY=2\nZ=3\n",
 "lone CR (classic Mac)": "X=1\rY=2\rZ=3\r",
 "blank+comment lines": "# c\n\nX=1\n\nY=2\n",
 "multiline double-quoted": 'X="a\nb"\nY=2\n',
 "error line then next": "bad line\r\nY=2\n",
}

def scan(s):
    return [b.original.line for b in p.parse_stream(io.StringIO(s))]

def patch_count_newline():
    p.Position.advance = lambda self, string: (setattr(self,'chars',self.chars+len(string)), setattr(self,'line',self.line+string.count("\n"))) and None

def patch_count_all():
    def adv(self, string):
        self.chars += len(string)
        self.line += len(re.findall(r"\r\n|\n|\r", string))
    p.Position.advance = adv

print("BEFORE FIX")
for k,v in cases.items(): print(f"  {k:28} -> {scan(v)}")

orig = None
patch_count_all()
print("\nAFTER: count('\\n') style")
patch_count_newline()
for k,v in cases.items(): print(f"  {k:28} -> {scan(v)}")

print("\nAFTER: _newline regex style")
patch_count_all()
for k,v in cases.items(): print(f"  {k:28} -> {scan(v)}")
EOF
